package main

import (
	"bytes"
	"fmt"
	"go/format"
	"maps"
	"slices"
	"strings"
)

const header = `// This Source Code Form is subject to the terms of the Mozilla Public
// License, v. 2.0. If a copy of the MPL was not distributed with this
// file, You can obtain one at http://mozilla.org/MPL/2.0/.
//
// Copyright 2026 maeshinshin.

// Code generated by ichorgen. DO NOT EDIT.

`

// typeName is the Go name of a materialized node: its path in words, so the name says where the object is.
func typeName(n *node) string {
	if n.path == "" {
		return "Config"
	}

	var b strings.Builder

	for seg := range strings.SplitSeq(n.path, ".") {
		if seg == "*" {
			b.WriteString("Entry")

			continue
		}

		b.WriteString(pascal(seg))
	}

	return b.String()
}

func pascal(s string) string {
	if s == "" {
		return s
	}

	return strings.ToUpper(s[:1]) + s[1:]
}

// writer collects the structs to emit and the imports they need.
type writer struct {
	g       *gen
	body    bytes.Buffer
	imports map[string]bool // mirror import names in use
	typed   bool            // the typedconfig package is used
	names   map[string]*node
	done    []*node
}

func (w *writer) goType(t *typ) string {
	switch t.kind {
	case tBasic:
		return t.name
	case tOpaque:
		if i := strings.IndexByte(t.name, '.'); i >= 0 {
			if t.name[:i] == mirrorPkg {
				w.typed = true
			} else {
				w.imports[t.name[:i]] = true
			}
		}

		return t.name
	case tStruct:
		if t.child.ref != nil {
			w.typed = true

			return mirrorPkg + "." + t.child.ref.name
		}

		w.queue(t.child)

		return typeName(t.child)
	case tPtr:
		return "*" + w.goType(t.elem)
	case tSlice:
		return "[]" + w.goType(t.elem)
	case tMap:
		return "map[string]" + w.goType(t.elem)
	}

	panic("unreachable")
}

func (w *writer) queue(n *node) {
	name := typeName(n)
	if other, ok := w.names[name]; ok {
		if other != n {
			panic("two objects of the schema are called " + name + ": " + other.path + " and " + n.path)
		}

		return
	}

	w.names[name] = n
	w.done = append(w.done, n)
}

// tag is the struct tag of a field: its JSON name, and where the setting goes in a Talos document.
func tag(f *field, optional bool) string {
	j := f.json
	if optional {
		j += ",omitempty"
	}

	switch {
	case f.docs != "":
		return fmt.Sprintf("`json:%q ichor:%q`", j, "docs="+f.docs)
	case len(f.sinks) == 0:
		return fmt.Sprintf("`json:%q`", j)
	}

	var parts []string
	for _, s := range f.sinks {
		parts = append(parts, s.String())
	}

	slices.Sort(parts)

	return fmt.Sprintf("`json:%q ichor:%q`", j, strings.Join(parts, ";"))
}

func (w *writer) writeNode(n *node) {
	name := typeName(n)

	if n.doc != "" {
		fmt.Fprintf(&w.body, "// %s %s\n", name, n.doc)
	} else {
		fmt.Fprintf(&w.body, "// %s is the object at %s.\n", name, orRoot(n.path))
	}

	fmt.Fprintf(&w.body, "type %s struct {\n", name)

	for _, f := range n.fields {
		if f.doc != "" {
			fmt.Fprintf(&w.body, "\t// %s\n", f.doc)
		} else if c := n.child(f.t); c != nil && c.doc != "" && c.ref == nil {
			fmt.Fprintf(&w.body, "\t// %s\n", c.doc)
		}

		if f.list {
			w.body.WriteString("\t// +listType=map\n\t// +listMapKey=name\n")
		}

		if f.required {
			w.body.WriteString("\t// +required\n")
		} else {
			w.body.WriteString("\t// +optional\n")
		}

		fmt.Fprintf(&w.body, "\t%s %s %s\n", pascal(f.json), w.goType(f.t), tag(f, !f.required))
	}

	w.body.WriteString("}\n\n")
}

func orRoot(p string) string {
	if p == "" {
		return "the root"
	}

	return p
}

// render writes the Go source of Ichor's schema.
func (g *gen) render() ([]byte, error) {
	w := &writer{g: g, imports: map[string]bool{}, names: map[string]*node{}}
	w.queue(g.root)

	for i := 0; i < len(w.done); i++ {
		w.writeNode(w.done[i])
	}

	var out bytes.Buffer

	out.WriteString(header)
	out.WriteString("package ichorconfig\n\n")

	if w.typed || len(w.imports) > 0 {
		out.WriteString("import (\n")

		for _, n := range slices.Sorted(maps.Keys(w.imports)) {
			fmt.Fprintf(&out, "\t%s %q\n", n, g.src.imports[n])
		}

		if w.typed {
			out.WriteString("\t\"github.com/maeshinshin/ichor/pkg/typedconfig\"\n")
		}

		out.WriteString(")\n\n")
	}

	out.Write(w.body.Bytes())

	b, err := format.Source(out.Bytes())
	if err != nil {
		return out.Bytes(), fmt.Errorf("formatting: %w", err)
	}

	return b, nil
}
